1	package codex
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
12		"github.com/entireio/cli/cmd/entire/cli/paths"
13	)
14	
15	// HooksFileName is the hooks config file used by Codex.
16	const HooksFileName = "hooks.json"
17	
18	// entireHookPrefixes identifies Entire hook commands.
19	var entireHookPrefixes = []string{
20		"entire ",
21		`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
22	}
23	
24	// InstallHooks installs Codex hooks in .codex/hooks.json.
25	func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
26		repoRoot, err := paths.WorktreeRoot(ctx)
27		if err != nil {
28			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
29			if err != nil {
30				return 0, fmt.Errorf("failed to get current directory: %w", err)
31			}
32		}
33	
34		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
35	
36		// Read existing hooks.json if present
37		var rawHooks map[string]json.RawMessage
38		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
39		if readErr == nil {
40			var hooksFile map[string]json.RawMessage
41			if err := json.Unmarshal(existingData, &hooksFile); err != nil {
42				return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
43			}
44			if hooksRaw, ok := hooksFile["hooks"]; ok {
45				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
46					return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
47				}
48			}
49		}
50	
51		if rawHooks == nil {
52			rawHooks = make(map[string]json.RawMessage)
53		}
54	
55		// Parse event types we manage
56		var sessionStart, userPromptSubmit, stop []MatcherGroup
57		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
58			return 0, err
59		}
60		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
61			return 0, err
62		}
63		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
64			return 0, err
65		}
66	
67		if force {
68			sessionStart = removeEntireHooks(sessionStart)
69			userPromptSubmit = removeEntireHooks(userPromptSubmit)
70			stop = removeEntireHooks(stop)
71		}
72	
73		// Build hook commands
74		var cmdPrefix string
75		if localDev {
76			cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks codex `
77		} else {
78			cmdPrefix = "entire hooks codex "
79		}
80		sessionStartCmd := cmdPrefix + "session-start"
81		userPromptSubmitCmd := cmdPrefix + "user-prompt-submit"
82		stopCmd := cmdPrefix + "stop"
83	
84		count := 0
85	
86		if !hookCommandExists(sessionStart, sessionStartCmd) {
87			sessionStart = addHook(sessionStart, sessionStartCmd)
88			count++
89		}
90		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
91			userPromptSubmit = addHook(userPromptSubmit, userPromptSubmitCmd)
92			count++
93		}
94		if !hookCommandExists(stop, stopCmd) {
95			stop = addHook(stop, stopCmd)
96			count++
97		}
98	
99		if count == 0 {
100			// Still ensure the feature flag is configured even if hooks
101			// were already present (e.g., manually installed).
102			if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
103				return 0, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
104			}
105			return 0, nil
106		}
107	
108		// Marshal modified types back
109		marshalHookType(rawHooks, "SessionStart", sessionStart)
110		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
111		marshalHookType(rawHooks, "Stop", stop)
112	
113		// Preserve existing top-level keys (e.g., $schema) by reusing the parsed file
114		topLevel := make(map[string]json.RawMessage)
115		if readErr == nil {
116			// Re-parse the original file to preserve all top-level keys
117			_ = json.Unmarshal(existingData, &topLevel) //nolint:errcheck // best-effort preservation
118		}
119		hooksJSON, err := json.Marshal(rawHooks)
120		if err != nil {
121			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
122		}
123		topLevel["hooks"] = hooksJSON
124	
125		// Write to file
126		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
127			return 0, fmt.Errorf("failed to create .codex directory: %w", err)
128		}
129	
130		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
131		if err != nil {
132			return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
133		}
134	
135		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
136			return 0, fmt.Errorf("failed to write hooks.json: %w", err)
137		}
138	
139		// Enable the codex_hooks feature in the project-level .codex/config.toml.
140		// This keeps the feature flag per-repo rather than global.
141		if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
142			return count, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
143		}
144	
145		return count, nil
146	}
147	
148	// UninstallHooks removes Entire hooks from Codex hooks.json.
149	func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
150		repoRoot, err := paths.WorktreeRoot(ctx)
151		if err != nil {
152			repoRoot = "."
153		}
154	
155		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
156		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
157		if err != nil {
158			return nil //nolint:nilerr // No hooks.json means nothing to uninstall
159		}
160	
161		var topLevel map[string]json.RawMessage
162		if err := json.Unmarshal(data, &topLevel); err != nil {
163			return fmt.Errorf("failed to parse hooks.json: %w", err)
164		}
165	
166		var rawHooks map[string]json.RawMessage
167		if hooksRaw, ok := topLevel["hooks"]; ok {
168			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
169				return fmt.Errorf("failed to parse hooks: %w", err)
170			}
171		}
172		if rawHooks == nil {
173			return nil
174		}
175	
176		var sessionStart, userPromptSubmit, stop []MatcherGroup
177		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
178			return err
179		}
180		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
181			return err
182		}
183		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
184			return err
185		}
186	
187		sessionStart = removeEntireHooks(sessionStart)
188		userPromptSubmit = removeEntireHooks(userPromptSubmit)
189		stop = removeEntireHooks(stop)
190	
191		marshalHookType(rawHooks, "SessionStart", sessionStart)
192		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
193		marshalHookType(rawHooks, "Stop", stop)
194	
195		if len(rawHooks) > 0 {
196			hooksJSON, err := json.Marshal(rawHooks)
197			if err != nil {
198				return fmt.Errorf("failed to marshal hooks: %w", err)
199			}
200			topLevel["hooks"] = hooksJSON
201		} else {
202			delete(topLevel, "hooks")
203		}
204	
205		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
206		if err != nil {
207			return fmt.Errorf("failed to marshal hooks.json: %w", err)
208		}
209		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
210			return fmt.Errorf("failed to write hooks.json: %w", err)
211		}
212		return nil
213	}
214	
215	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
216	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
217		repoRoot, err := paths.WorktreeRoot(ctx)
218		if err != nil {
219			repoRoot = "."
220		}
221	
222		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
223		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
224		if err != nil {
225			return false
226		}
227	
228		var hooksFile HooksFile
229		if err := json.Unmarshal(data, &hooksFile); err != nil {
230			return false
231		}
232	
233		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
234			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
235			hasEntireHook(hooksFile.Hooks.Stop)
236	}
237	
238	// --- Helpers ---
239	
240	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
241		if data, ok := rawHooks[hookType]; ok {
242			if err := json.Unmarshal(data, target); err != nil {
243				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
244			}
245		}
246		return nil
247	}
248	
249	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
250		if len(groups) == 0 {
251			delete(rawHooks, hookType)
252			return
253		}
254		data, err := json.Marshal(groups)
255		if err != nil {
256			return
257		}
258		rawHooks[hookType] = data
259	}
260	
261	func hookCommandExists(groups []MatcherGroup, command string) bool {
262		for _, group := range groups {
263			for _, hook := range group.Hooks {
264				if hook.Command == command {
265					return true
266				}
267			}
268		}
269		return false
270	}
271	
272	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
273		entry := HookEntry{
274			Type:    "command",
275			Command: command,
276			Timeout: 30,
277		}
278	
279		// Add to an existing group with null matcher, or create a new one
280		for i, group := range groups {
281			if group.Matcher == nil {
282				groups[i].Hooks = append(groups[i].Hooks, entry)
283				return groups
284			}
285		}
286		return append(groups, MatcherGroup{
287			Matcher: nil,
288			Hooks:   []HookEntry{entry},
289		})
290	}
291	
292	func isEntireHook(command string) bool {
293		for _, prefix := range entireHookPrefixes {
294			if strings.HasPrefix(command, prefix) {
295				return true
296			}
297		}
298		return false
299	}
300	
301	func hasEntireHook(groups []MatcherGroup) bool {
302		for _, group := range groups {
303			for _, hook := range group.Hooks {
304				if isEntireHook(hook.Command) {
305					return true
306				}
307			}
308		}
309		return false
310	}
311	
312	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
313		result := make([]MatcherGroup, 0, len(groups))
314		for _, group := range groups {
315			filtered := make([]HookEntry, 0, len(group.Hooks))
316			for _, hook := range group.Hooks {
317				if !isEntireHook(hook.Command) {
318					filtered = append(filtered, hook)
319				}
320			}
321			if len(filtered) > 0 {
322				group.Hooks = filtered
323				result = append(result, group)
324			}
325		}
326		return result
327	}
328	
329	// configFileName is the Codex config file name.
330	const configFileName = "config.toml"
331	
332	// featureLine is the TOML line that enables the codex_hooks feature.
333	const featureLine = "codex_hooks = true"
334	
335	// ensureProjectFeatureEnabled writes features.codex_hooks = true to the
336	// project-level .codex/config.toml. This keeps the feature flag per-repo.
337	func ensureProjectFeatureEnabled(repoRoot string) error {
338		configPath := filepath.Join(repoRoot, ".codex", configFileName)
339	
340		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
341		if err != nil && !os.IsNotExist(err) {
342			return fmt.Errorf("failed to read config.toml: %w", err)
343		}
344	
345		content := string(data)
346		if strings.Contains(content, featureLine) {
347			return nil
348		}
349	
350		if strings.Contains(content, "[features]") {
351			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
352		} else {
353			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
354				content += "\n"
355			}
356			content += "\n[features]\n" + featureLine + "\n"
357		}
358	
359		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
360			return fmt.Errorf("failed to create .codex directory: %w", err)
361		}
362		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
363			return fmt.Errorf("failed to write config.toml: %w", err)
364		}
365		return nil
366	}
