// Shared constants

/**
 * Branch name for storing checkpoint data (sessions, transcripts, metadata).
 * V1 format uses 0-indexed session folders with explicit paths in CheckpointSummary.
 */
export const CHECKPOINT_BRANCH = "entire/checkpoints/v1";

/**
 * Branch name for storing trail data (metadata, discussion).
 * Trails track the lifecycle of work on a branch.
 */
export const TRAILS_BRANCH = "entire/trails/v1";

/**
 * Fallback agent name for legacy checkpoints created before the CLI started
 * writing agent metadata. Should not be needed for new checkpoints.
 */
export const LEGACY_FALLBACK_AGENT_NAME = "Claude Code";

