it("falls back to single session from agent field when sessions is null", () => {
  const row = makeRow({ sessions: null, agent: "Cursor", prompt: "do stuff", steps: 2 });
  const result = parseSessionsFromRow(row);

  expect(result).toEqual([{ prompt: "do stuff", agent: "Cursor", steps: 2 }]);
});

